import React from 'react';

const COLOR_META = {
  green: { emoji: '🟢', label: 'Low' },
  yellow: { emoji: '🟡', label: 'Moderate' },
  orange: { emoji: '🟠', label: 'High' },
  red: { emoji: '🔴', label: 'Very High / Recurring' },
};

export default function Heatmap({ zones }) {
  if (!zones) return null;
  const max = Math.max(1, ...zones.map((z) => z.incidents));

  return (
    <div className="card heatmap-card">
      <h2>Interactive Harassment Incident Heatmap</h2>
      <p className="muted">Fictional city grid, clustered by threat zone. Repeating incidents escalate a zone's severity.</p>
      <div className="heatmap-grid">
        {zones.map((z) => {
          const meta = COLOR_META[z.color];
          const intensity = z.incidents / max;
          return (
            <div
              key={z.id}
              className={`heat-zone heat-${z.color}`}
              style={{ '--intensity': intensity }}
            >
              <span className="heat-emoji">{meta.emoji}</span>
              <strong>{z.id}</strong>
              <span className="heat-sub">{meta.label}</span>
              <span className="heat-count">{z.incidents} incident{z.incidents === 1 ? '' : 's'}</span>
              {z.recurring && <span className="heat-recurring">Recurring cluster</span>}
            </div>
          );
        })}
      </div>
    </div>
  );
}
